  private val cache = HashMap<String, Path?>()

  /** Path in a 24 × 24 box for a built-in [name], or for raw SVG path data in [customPath]. */
  fun path(name: String, customPath: String?): Path? {
    val data = if (!customPath.isNullOrBlank()) customPath
      else paths[name.lowercase()] ?: paths[aliases[name.lowercase()] ?: ""] ?: paths["home"]
    val key = data ?: return null
    return cache.getOrPut(key) {
      try { PathParser.createPathFromPathData(key) } catch (t: Throwable) {
        Log.w("LiquidGlassTabs", "Invalid icon path data, using no icon", t); null
      }
    }
  }
